-- migra-133 (09/10/2026): las paginas explican el aura como recurso (migra-132) en los nueve idiomas.
--  · «¿Que es Deltha?», apartado «Destacar una noticia»: el segundo parrafo (creditos por unidad de aura) pasa a explicar lo que usa de aura.
--  · «Como empezar», apartado Aura: el ejemplo del destacado dice lo que usa.
-- Marcadores nuevos de page_body(): {pincost} {pincostorig} {aurafloor} {pinmin} {pinhorig} (lib/app.php), asi el texto sigue bien si cambian las cifras.
-- Son REPLACE del texto exacto que dejaron migra-112 y migra-122: si un parrafo se edito en admin -> Paginas, ese idioma no cambia y hay que pegarlo a mano.
SET NAMES utf8mb4;
UPDATE pages SET body = REPLACE(body, '<p>Tú también puedes. Cada vez que tu aura alcanza una unidad entera nueva (de 6,9 a 7, por ejemplo) ganas un destacado, y cuando tienes alguno te aparece el botón en las tarjetas de lo que ya está en portada: la noticia que elijas irá la primera durante media hora. Solo cuentan las unidades que no habías alcanzado antes: llegar a 6, bajar a 5,5 y volver a 6 no da otro. Puedes tener una destacada a la vez; destacar otra sustituye la anterior.</p>', '<p>Tú también puedes, usando tu aura: destacar usa {pincost} de aura en las portadas (la noticia va la primera {pinmin} minutos) y {pincostorig} en Originales ({pinhorig} horas), y nunca puedes bajar de {aurafloor}. El botón aparece, con lo que usa al lado, en las tarjetas de lo que ya está en portada y en los originales. Puedes tener una destacada a la vez; destacar otra sustituye la anterior y el aura usada no se recupera. Si hay varias esperando, van por turno.</p>') WHERE slug = 'que-es';
UPDATE pages SET body = REPLACE(body, '<p>Tu també pots. Cada vegada que la teva aura arriba a una unitat sencera nova (de 6,9 a 7, per exemple) guanyes un destacat, i quan en tens algun t''apareix el botó a les targetes del que ja és a portada: la notícia que triïs anirà la primera durant mitja hora. Només compten les unitats que no havies assolit abans: arribar a 6, baixar a 5,5 i tornar a 6 no en dona un altre. Pots tenir una destacada alhora; destacar-ne una altra substitueix l''anterior.</p>', '<p>Tu també pots, fent servir la teva aura: destacar fa servir {pincost} d''aura a les portades (la notícia va la primera {pinmin} minuts) i {pincostorig} a Originals ({pinhorig} hores), i mai no pots baixar de {aurafloor}. El botó apareix, amb el que fa servir al costat, a les targetes del que ja és a portada i als originals. Pots tenir una destacada alhora; destacar-ne una altra substitueix l''anterior i l''aura usada no es recupera. Si n''hi ha diverses esperant, van per torn.</p>') WHERE slug = 'que-es.ca';
UPDATE pages SET body = REPLACE(body, '<p>Zuk ere egin dezakezu. Zure aurak unitate oso berri bat lortzen duen bakoitzean (6,9tik 7ra, adibidez) nabarmentze bat irabazten duzu, eta baduzunean botoia agertzen zaizu dagoeneko azalean dagoenaren txarteletan: aukeratzen duzun albistea lehena izango da ordu erdiz. Aurretik lortu gabeko unitateek bakarrik balio dute: 6ra iritsi, 5,5era jaitsi eta berriro 6ra igotzeak ez du beste bat ematen. Nabarmendu bakarra izan dezakezu aldi berean; beste bat nabarmentzeak aurrekoa ordezkatzen du.</p>', '<p>Zuk ere egin dezakezu, zure aura erabiliz: nabarmentzeak {pincost} aura erabiltzen du azaletan (albistea lehena izango da {pinmin} minutuz) eta {pincostorig} Originaletan ({pinhorig} ordu), eta inoiz ezin zara {aurafloor}-tik jaitsi. Botoia, erabiltzen duena ondoan duela, dagoeneko azalean dagoenaren txarteletan eta originaletan agertzen da. Nabarmendu bakarra izan dezakezu aldi berean; beste bat nabarmentzeak aurrekoa ordezkatzen du eta erabilitako aura ez da berreskuratzen. Hainbat zain badaude, txandaka doaz.</p>') WHERE slug = 'que-es.eu';
UPDATE pages SET body = REPLACE(body, '<p>Ti tamén podes. Cada vez que a túa aura acada unha unidade enteira nova (de 6,9 a 7, por exemplo) gañas un destacado, e cando tes algún aparéceche o botón nas tarxetas do que xa está en portada: a noticia que escollas irá a primeira durante media hora. Só contan as unidades que non acadaras antes: chegar a 6, baixar a 5,5 e volver a 6 non dá outro. Podes ter unha destacada á vez; destacar outra substitúe a anterior.</p>', '<p>Ti tamén podes, usando a túa aura: destacar usa {pincost} de aura nas portadas (a noticia vai a primeira {pinmin} minutos) e {pincostorig} en Orixinais ({pinhorig} horas), e nunca podes baixar de {aurafloor}. O botón aparece, co que usa ao lado, nas tarxetas do que xa está en portada e nos orixinais. Podes ter unha destacada á vez; destacar outra substitúe a anterior e a aura usada non se recupera. Se hai varias agardando, van por quenda.</p>') WHERE slug = 'que-es.gl';
UPDATE pages SET body = REPLACE(body, '<p>You can too. Every time your aura reaches a new whole unit (from 6.9 to 7, say) you earn a highlight, and when you have one the button appears on the cards of what is already on a front page: the story you pick goes first for half an hour. Only units you had never reached before count: getting to 6, dropping to 5.5 and climbing back to 6 does not earn another. You can have one featured story at a time; featuring another replaces it.</p>', '<p>You can too, using your aura: featuring uses {pincost} aura on the front pages (the story goes first for {pinmin} minutes) and {pincostorig} in Originals ({pinhorig} hours), and you can never drop below {aurafloor}. The button appears, with the amount it uses next to it, on the cards of what is already on a front page and on originals. You can have one featured story at a time; featuring another replaces it and the aura used is not recovered. If several are waiting, they take turns.</p>') WHERE slug = 'que-es.en';
UPDATE pages SET body = REPLACE(body, '<p>Vous le pouvez aussi. Chaque fois que votre aura atteint une nouvelle unité entière (de 6,9 à 7, par exemple) vous gagnez une mise en avant, et quand vous en avez une le bouton apparaît sur les cartes de ce qui est déjà en une : l''actualité que vous choisissez passe en tête pendant une demi-heure. Seules comptent les unités jamais atteintes auparavant : arriver à 6, redescendre à 5,5 et remonter à 6 n''en donne pas une autre. Vous ne pouvez en avoir qu''une à la fois ; en mettre une autre en avant remplace la précédente.</p>', '<p>Vous le pouvez aussi, en utilisant votre aura : mettre en avant utilise {pincost} d''aura dans les unes (l''actualité passe en tête {pinmin} minutes) et {pincostorig} dans les Originaux ({pinhorig} heures), et vous ne pouvez jamais descendre sous {aurafloor}. Le bouton apparaît, avec ce qu''il utilise à côté, sur les cartes de ce qui est déjà en une et sur les originaux. Vous ne pouvez en avoir qu''une à la fois ; en mettre une autre en avant remplace la précédente et l''aura utilisée ne se récupère pas. S''il y en a plusieurs en attente, elles passent à tour de rôle.</p>') WHERE slug = 'que-es.fr';
UPDATE pages SET body = REPLACE(body, '<p>Du kannst das auch. Jedes Mal, wenn deine Aura eine neue ganze Einheit erreicht (von 6,9 auf 7 etwa), bekommst du eine Hervorhebung, und sobald du eine hast, erscheint der Knopf auf den Karten dessen, was schon auf einer Startseite steht: Die Meldung, die du wählst, steht eine halbe Stunde lang vorn. Nur Einheiten zählen, die du vorher nie erreicht hattest: Auf 6 kommen, auf 5,5 fallen und wieder auf 6 steigen bringt keine weitere. Du kannst jeweils eine Meldung hervorheben; eine andere hervorzuheben ersetzt die vorige.</p>', '<p>Du kannst das auch, mit deiner Aura: Hervorheben verwendet {pincost} Aura auf den Startseiten (die Meldung steht {pinmin} Minuten vorn) und {pincostorig} bei den Originalen ({pinhorig} Stunden), und unter {aurafloor} kommst du nie. Der Knopf erscheint, mit der Menge daneben, auf den Karten dessen, was schon auf einer Startseite steht, und bei den Originalen. Du kannst jeweils eine Meldung hervorheben; eine andere hervorzuheben ersetzt die vorige, und die verwendete Aura kommt nicht zurück. Warten mehrere, kommen sie der Reihe nach dran.</p>') WHERE slug = 'que-es.de';
UPDATE pages SET body = REPLACE(body, '<p>Puoi farlo anche tu. Ogni volta che la tua aura raggiunge una nuova unità intera (da 6,9 a 7, per esempio) guadagni un''evidenza, e quando ne hai una ti compare il pulsante nelle schede di ciò che è già in prima pagina: la notizia che scegli andrà per prima per mezz''ora. Contano solo le unità mai raggiunte prima: arrivare a 6, scendere a 5,5 e risalire a 6 non ne dà un''altra. Puoi averne una in evidenza alla volta; evidenziarne un''altra sostituisce la precedente.</p>', '<p>Puoi farlo anche tu, usando la tua aura: mettere in evidenza usa {pincost} di aura nelle prime pagine (la notizia va per prima per {pinmin} minuti) e {pincostorig} negli Originali ({pinhorig} ore), e non puoi mai scendere sotto {aurafloor}. Il pulsante compare, con quanto usa accanto, nelle schede di ciò che è già in prima pagina e negli originali. Puoi averne una in evidenza alla volta; evidenziarne un''altra sostituisce la precedente e l''aura usata non si recupera. Se ce ne sono diverse in attesa, vanno a turno.</p>') WHERE slug = 'que-es.it';
UPDATE pages SET body = REPLACE(body, '<p>Tu também podes. De cada vez que a tua aura atinge uma unidade inteira nova (de 6,9 para 7, por exemplo) ganhas um destaque, e quando tens algum aparece-te o botão nos cartões do que já está em capa: a notícia que escolheres irá em primeiro durante meia hora. Só contam as unidades que nunca tinhas atingido: chegar a 6, descer a 5,5 e voltar a 6 não dá outro. Podes ter uma destacada de cada vez; destacar outra substitui a anterior.</p>', '<p>Tu também podes, usando a tua aura: destacar usa {pincost} de aura nas capas (a notícia vai em primeiro {pinmin} minutos) e {pincostorig} nos Originais ({pinhorig} horas), e nunca podes baixar de {aurafloor}. O botão aparece, com o que usa ao lado, nos cartões do que já está em capa e nos originais. Podes ter uma destacada de cada vez; destacar outra substitui a anterior e a aura usada não se recupera. Se houver várias à espera, vão por turnos.</p>') WHERE slug = 'que-es.pt';
UPDATE pages SET body = REPLACE(body, '(por ejemplo, <b>Destacar</b> una noticia unos minutos en portada)', '(por ejemplo, <b>Destacar</b> una noticia unos minutos en portada, que usa {pincost} de aura; nunca bajarás de {aurafloor})') WHERE slug = 'empezar';
UPDATE pages SET body = REPLACE(body, '(per exemple, <b>Destacar</b> una notícia uns minuts a portada)', '(per exemple, <b>Destacar</b> una notícia uns minuts a portada, que fa servir {pincost} d''aura; mai no baixaràs de {aurafloor})') WHERE slug = 'empezar.ca';
UPDATE pages SET body = REPLACE(body, '(adibidez, albiste bat minutu batzuez azalean <b>nabarmentzea</b>)', '(adibidez, albiste bat minutu batzuez azalean <b>nabarmentzea</b>, {pincost} aura erabiltzen duena; inoiz ez zara {aurafloor}-tik jaitsiko)') WHERE slug = 'empezar.eu';
UPDATE pages SET body = REPLACE(body, '(por exemplo, <b>Destacar</b> unha noticia uns minutos en portada)', '(por exemplo, <b>Destacar</b> unha noticia uns minutos en portada, que usa {pincost} de aura; nunca baixarás de {aurafloor})') WHERE slug = 'empezar.gl';
UPDATE pages SET body = REPLACE(body, '(for instance, <b>featuring</b> an item on the front page for a few minutes)', '(for instance, <b>featuring</b> an item on the front page for a few minutes, which uses {pincost} aura; you will never drop below {aurafloor})') WHERE slug = 'empezar.en';
UPDATE pages SET body = REPLACE(body, '(par exemple, <b>Mettre en avant</b> une nouvelle quelques minutes en une)', '(par exemple, <b>Mettre en avant</b> une nouvelle quelques minutes en une, ce qui utilise {pincost} d''aura ; vous ne descendrez jamais sous {aurafloor})') WHERE slug = 'empezar.fr';
UPDATE pages SET body = REPLACE(body, '(zum Beispiel, eine Meldung ein paar Minuten auf der Titelseite <b>hervorzuheben</b>)', '(zum Beispiel, eine Meldung ein paar Minuten auf der Titelseite <b>hervorzuheben</b>, was {pincost} Aura verwendet; unter {aurafloor} fällst du dabei nie)') WHERE slug = 'empezar.de';
UPDATE pages SET body = REPLACE(body, '(per esempio, <b>Mettere in evidenza</b> una notizia per qualche minuto in prima pagina)', '(per esempio, <b>Mettere in evidenza</b> una notizia per qualche minuto in prima pagina, che usa {pincost} di aura; non scenderai mai sotto {aurafloor})') WHERE slug = 'empezar.it';
UPDATE pages SET body = REPLACE(body, '(por exemplo, <b>Destacar</b> uma notícia uns minutos na primeira página)', '(por exemplo, <b>Destacar</b> uma notícia uns minutos na primeira página, que usa {pincost} de aura; nunca baixarás de {aurafloor})') WHERE slug = 'empezar.pt';
